h1 { font-size: 30px; margin: 0 0 24px; }
.project-form, .task-form { display: grid; gap: 8px; max-width: 420px; }
input, button { box-sizing: border-box; font: inherit; }
input { border: 1px solid #aeb8c6; border-radius: 5px; padding: 9px 10px; }
button { background: #2459a6; border: 0; border-radius: 5px; color: white; cursor: pointer; padding: 9px 14px; }
button:hover { background: #194985; }
.project-form button { justify-self: start; margin-top: 4px; }
.task-form button { justify-self: start; margin-top: 4px; }
.task-form { margin-top: 24px; }
#task-filter { display: block; font: inherit; margin: 6px 0 16px; padding: 7px; }
.task-list { display: grid; gap: 8px; }
.task-row { align-items: center; background: white; border: 1px solid #d9dee7; border-radius: 6px; display: flex; gap: 10px; padding: 12px 16px; }
.task-row span { flex: 1; }
.task-row input { width: 18px; height: 18px; }
.alert { color: #a12622; font-weight: 600; }
.project-list { display: grid; gap: 10px; margin-top: 28px; }
.project-row { align-items: center; background: white; border: 1px solid #d9dee7; border-radius: 6px; display: flex; justify-content: space-between; padding: 14px 16px; }

